"import { MockApiServer } from './server';

async function main(): Promise<void> {
  const port = process.env.PORT ? Number(process.env.PORT) : 3000;
  const server = new MockApiServer({
    port,
    minDelayMs: 200,
    maxDelayMs: 500,
    failureRate: 0.1,
    autoProgressStatus: true,
    autoProgressIntervalMs: 2500,
  });

  const baseUrl = await server.start();
  console.log(`========================================================`);
  console.log(`🚀 Insurtech Mock API Server running at ${baseUrl}`);
  console.log(`   - Simulated latency: 200ms - 500ms`);
  console.log(`   - Simulated transient 503 failure rate: 10%`);
  console.log(`   - Seeded initial claim: CLM-001`);
  console.log(`   - Auto status progression: enabled (2.5s interval)`);
  console.log(`========================================================`);

  const shutdown = async () => {
    console.log('\nShutting down Mock API Server...');
    await server.stop();
    process.exit(0);
  };

  process.on('SIGINT', () => void shutdown());
  process.on('SIGTERM', () => void shutdown());
}

void main();
