/**
 * Validates SDK initialization options.
 */
export function validateSDKConfig(config: {
  apiKey?: unknown;
  environment?: unknown;
  timeout?: unknown;
}): void {
  const fields: Record<string, string> = {};

  if (
    !config ||
    typeof config.apiKey !== 'string' ||
    config.apiKey.trim() === ''
  ) {
    fields.apiKey = 'required';
  }

  const validEnvs: Environment[] = ['sandbox', 'production'];
  if (
    !config ||
    typeof config.environment !== 'string' ||
    !validEnvs.includes(config.environment as Environment)
  ) {
    fields.environment = 'must be either "sandbox" or "production"';
  }

  if (config?.timeout !== undefined) {
    if (
      typeof config.timeout !== 'number' ||
      !Number.isFinite(config.timeout) ||
      config.timeout <= 0
    ) {
      fields.timeout = 'must be a positive number of milliseconds';
    }
  }

  if (Object.keys(fields).length > 0) {
    throw new ValidationError('Invalid SDK configuration', fields);
  }
}

