  public async list(claimId: string): Promise<ClaimDocumentDto[]> {
    assertValidClaimId(claimId);

    return this.http.request<ClaimDocumentDto[]>({
      method: 'GET',
      path: `/api/v1/claims/${encodeURIComponent(claimId.trim())}/documents`,
    });
  }
}
